def nge_brute(a):
    n=len(a); ans=[-1]*n
    for i in range(n):
        for j in range(i+1,n):
            if a[j]>a[i]:
                ans[i]=a[j]; break
    return ans

def next_greater(a):
    n=len(a); ans=[-1]*n; st=[]
    for i,x in enumerate(a):
        while st and a[st[-1]] < x:
            ans[st.pop()] = x
        st.append(i)
    return ans
